package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ClonePair5129DifferenceFindingTest {

    private final ClonePair5129 subject = new ClonePair5129();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: exception.
     * Difference manifestation: the methods differ in thrown exceptions or normal completion.
     */
    @Test
    @BehavioralDifference(DifferenceType.EXCEPTION)
    void methodsDisagreeWhenTheSecondSetContainsNullAndTheFirstSetRejectsNullLookups() {
        // method1 calls setA.contains(null), which a TreeSet with natural ordering rejects,
        // whereas method2 delegates to setB.equals(setA), which swallows the failed lookup.
        Set<String> sortedSet = new TreeSet<>(List.of("a"));
        Set<String> setWithNull = new HashSet<>(Collections.singletonList(null));

        assertThrows(NullPointerException.class, () -> subject.method1(sortedSet, setWithNull));
        assertFalse(subject.method2(sortedSet, setWithNull));
    }
}
